from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.parse_movement_line import parse_movement_line


def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    if idle_days < 1:
        raise ValueError("idle_days must be at least 1")

    records = list(lines)
    on_hand_map = on_hand_by_location(records, case_sizes, as_of_day=today)
    sku_totals = {}
    for (sku, loc), qty in on_hand_map.items():
        sku_totals[sku] = sku_totals.get(sku, 0) + qty

    candidates = {sku for sku, total in sku_totals.items() if total > 0}
    if not candidates:
        return []

    last_ship_day = {}
    first_movement_day = {}

    for line in records:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        m = parse_movement_line(text, case_sizes)
        if m["day"] > today:
            continue
        sku = m["sku"]
        if sku not in candidates:
            continue
        day = m["day"]
        if sku not in first_movement_day or day < first_movement_day[sku]:
            first_movement_day[sku] = day
        if m["type"] == "SHP":
            if sku not in last_ship_day or day > last_ship_day[sku]:
                last_ship_day[sku] = day

    dead = []
    for sku in candidates:
        # Use last shipment if it exists, otherwise use the first movement
        ref_day = last_ship_day.get(sku, first_movement_day.get(sku))
        if ref_day is not None and (today - ref_day >= idle_days):
            dead.append(sku)

    return sorted(dead)
"}}}
