from typing import Iterable, List, Mapping, Tuple, Set
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location


def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    system_stock = on_hand_by_location(lines, case_sizes)
    normalized_counts = {}
    counted_locations: Set[str] = set()

    for (raw_sku, raw_loc), qty in counts.items():
        if qty < 0:
            raise ValueError("Counted quantity cannot be negative")
        sku = normalize_sku(raw_sku)
        parse_location(raw_loc)
        loc = raw_loc.strip().upper()
        normalized_counts[(sku, loc)] = normalized_counts.get((sku, loc), 0) + qty
        counted_locations.add(loc)

    variances = {}
    for (sys_sku, sys_loc), sys_qty in system_stock.items():
        if sys_loc in counted_locations:
            counted_qty = normalized_counts.get((sys_sku, sys_loc), 0)
            if counted_qty != sys_qty:
                variances[(sys_sku, sys_loc)] = counted_qty - sys_qty

    for (count_sku, count_loc), counted_qty in normalized_counts.items():
        sys_qty = system_stock.get((count_sku, count_loc), 0)
        if counted_qty != sys_qty:
            variances[(count_sku, count_loc)] = counted_qty - sys_qty

    result = [(sku, loc, var) for (sku, loc), var in variances.items()]
    return sorted(result, key=lambda x: (x[1], x[0]))"}}}
